const menu=document.querySelector('#menu'),nav=document.querySelector('#links');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu')}menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu')};nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
const english=document.createElement('a');english.href='en.html';english.hreflang='en';english.lang='en';english.textContent='English';nav.append(english);
const need=document.querySelector('#need');
function updateNeed(){const candidate=need.value==='Candidature spontanée';document.querySelector('#org-label').textContent=candidate?'Organisation ou statut professionnel':'Organisation';document.querySelector('[name=org]').placeholder=candidate?'Ex. indépendant, étudiant, salarié':'Entreprise ou institution'}
need.addEventListener('change',updateNeed);
const id=new URLSearchParams(location.search).get('expertise');const selected=allExpertises.find(({item})=>expertiseId(item[1])===id);
if(selected){need.value=selected.group==='Cybersécurité, risques & résilience'?'Cybersécurité & résilience':'Conseil & expertise';document.querySelector('[name=message]').value='Domaine : '+selected.item[1]+' — '}
updateNeed();
document.querySelector('#request').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);document.querySelector('#draft').textContent=`Objet : ${f.get('besoin')}\nNom : ${f.get('nom')}\nOrganisation : ${f.get('org')}\nE-mail : ${f.get('email')}\n${f.get('solution')?'Solution : '+f.get('solution')+'\n':''}\n${f.get('message')}`;document.querySelector('#form-result').hidden=false;const status=document.querySelector('#request-status'),button=e.target.querySelector('[type=submit]');button.disabled=true;status.textContent='Enregistrement en cours…';try{const payload=Object.fromEntries(f.entries());payload.consent=f.get('consent')==='on';const response=await fetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error('request');const result=await response.json();status.textContent='Demande enregistrée localement. Référence : '+result.id+'. Aucun e-mail envoyé.';}catch{status.textContent='Enregistrement indisponible : votre demande n’a pas été transmise. Vous pouvez la télécharger ou la copier.';}finally{button.disabled=false}};document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#draft').textContent);document.querySelector('#copy').textContent='Demande copiée'}catch{document.querySelector('#copy').textContent='Sélectionnez le texte pour le copier'}};
document.querySelectorAll('[data-need]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#need').value=link.dataset.need;updateNeed();if(link.dataset.expertise){const message=document.querySelector('[name=message]');const prefix='Domaine : '+link.dataset.expertise+' — ';if(!message.value.trim()||message.value.startsWith('Domaine : '))message.value=prefix+message.value.replace(/^Domaine : .*? — /,'')}}));
document.querySelector('#download-request').onclick=()=>{const url=URL.createObjectURL(new Blob([document.querySelector('#draft').textContent],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='demande-DSIG.txt';a.click();URL.revokeObjectURL(url)};
